steps.text:
/*
	VIOC_merc_ops.sqf - parche merc_ops de VIOC (2026-10-20). No es del autor de la mision.
	Lo compila init.sqf SOLO en el servidor, despues de VIOC_mercenaries.sqf: usa sus funciones y envuelve dos de ellas
	(VIOC_MERC_fnc_candidates y VIOC_MERC_fnc_kit). Sin mercenaries activo (VIOC_MERC_ON) no hace nada.

	1) Ataque inicial (VIOC_MERC_RAID): una vez por partida, entre VIOC_MOPS_RAID_T0 y VIOC_MOPS_RAID_T1 s, el bando al que
	   sirven los mercenarios (solo Oeste/Este; la guerrilla no) contrata una escuadra de ION contra la capital, si la
	   capital no es suya y no es retaguardia de su duenio (front_line). Escuadra: la de una zona de mercenaries sin el
	   jefe (8-12 hombres con el tope VIOC_MERC_MAX_MEN, 1-2 vehiculos de ruedas). Sale de un pueblo propio (o del HQ) a
	   1.2-6 km de la capital, con paso por tierra, sin jugadores a VIOC_MOPS_HIDE_R m ni a la vista, y solo si cabe en el
	   presupuesto de IA (VIOC_MERC_fnc_room: tope de perf_cleanup menos el margen de mercenaries). Va en sus vehiculos y
	   busca y destruye en la capital. Lo que queda se borra a los VIOC_MOPS_RAID_LIFE s (o si mueren todos), sin jugadores
	   a 900 m ni a la vista. Aviso de inteligencia a los jugadores enemigos, como los contratos de mercenaries.
	   OJO: no entra en el guardado; si se carga una partida guardada antes de VIOC_MOPS_RAID_T1, puede repetirse.
	2) Ultimos pueblos (VIOC_MERC_LAST): si el bando al que sirven queda con 1 o 2 pueblos, esos pueblos son zonas de
	   mercenarios (jefe con escolta, tipo "last"), despues del HQ y antes que nada mas. Mismo tope de zonas
	   (VIOC_MERC_MAX_ZONES), presupuesto, separacion, enfriamiento y aparicion cerca de los jugadores de mercenaries.
	3) Habilidad: al crear cada mercenario, despues del kit de mercenaries, VIOC_MOPS_SKILL (punteria ~0.55-0.61, el
	   francotirador ~0.72-0.78; deteccion, reaccion y recarga altas; sin llegar a 1). Mas que la guerrilla (habilidad
	   general 0.4-0.6 de Common_CreateUnit) sin ser imbatibles. Nada los baja despues: ai_allies solo toca bandos con
	   jugador y BIS_fnc_EXP_camp_setSkill (Init_CommonConstants) corre una vez al inicio, antes de que existan.

	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_MOPS_fnc_info);   call VIOC_MOPS_fnc_raidNow; (ataque ya, sin plazo)
*/
if (!isServer) exitWith {};
if (isNil "VIOC_MERC_ON" || {!VIOC_MERC_ON}) exitWith {diag_log "[VIOC merc_ops] mercenaries apagado: no hace nada"};

VIOC_MOPS_RAID = (["VIOC_MERC_RAID", 1] call VIOC_MERC_fnc_par) > 0;
VIOC_MOPS_LAST = (["VIOC_MERC_LAST", 1] call VIOC_MERC_fnc_par) > 0;
VIOC_MOPS_RAID_T0 = 600;            // s: el ataque no sale antes
VIOC_MOPS_RAID_T1 = 2700;           // s: despues ya no es "al inicio" y se descarta
VIOC_MOPS_RAID_R = [1200, 6000];    // m de la salida a la capital
VIOC_MOPS_RAID_LIFE = 2700;         // s: despues se borra lo que quede (lejos de los jugadores)
VIOC_MOPS_HIDE_R = 900;             // m sin jugadores alrededor de la salida
VIOC_MOPS_SKILL = [["general", 0.85], ["aimingAccuracy", 0.55], ["aimingShake", 0.7], ["aimingSpeed", 0.75], ["spotDistance", 0.9],
	["spotTime", 0.85], ["courage", 1], ["reloadSpeed", 0.9], ["commanding", 0.9]];
VIOC_MOPS_RAID_STATE = ["descartado", "espera"] select VIOC_MOPS_RAID;	// espera / en curso / terminado / descartado
VIOC_MOPS_RAID_FORCE = false;
VIOC_MOPS_RAID_INFO = [];           // [capital, hombres, vehiculos, salida]

VIOC_MOPS_fnc_log = {
	params ["_m"];
	_m = "[merc_ops] " + _m;
	[_m] call VIOC_MERC_fnc_log;
};

//--- 3) Habilidad
VIOC_MOPS_fnc_kitOrig = VIOC_MERC_fnc_kit;
VIOC_MERC_fnc_kit = {
	params ["_u", "_role"];
	_this call VIOC_MOPS_fnc_kitOrig;
	{
		private _b = if ((_x select 0) == "aimingAccuracy" && {_role == "sniper"}) then {0.17} else {0};
		_u setSkill [_x select 0, ((_x select 1) + _b + random 0.06) min 0.95];
	} forEach VIOC_MOPS_SKILL;
};

//--- 2) Ultimos pueblos
VIOC_MOPS_fnc_candOrig = VIOC_MERC_fnc_candidates;
VIOC_MERC_fnc_candidates = {
	params ["_side"];
	private _res = _this call VIOC_MOPS_fnc_candOrig;
	if (!VIOC_MOPS_LAST) exitWith {_res};
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _own = CTI_Towns select {(_x getVariable ["cti_town_sideID", -1]) == _sid};
	if (count _own == 0 || {count _own > 2}) exitWith {_res};
	private _have = _res apply {_x select 3};
	private _last = [];
	{
		if !(_x in _have) then {
			_last pushBack [format ["town_%1", _x getVariable ["cti_town_name", "pueblo"]], "last", _x getVariable ["cti_town_name", "un pueblo"], _x, getPosATL _x call VIOC_MERC_fnc_p0];
		};
	} forEach _own;
	//--- el HQ primero; despues los ultimos pueblos (los que ya eran capital o aerodromo siguen con su tipo)
	(_res select {(_x select 1) == "hq"}) + (_res select {(_x select 1) != "hq" && {(_x select 3) in _own}}) + _last
};

//--- 1) Ataque inicial
VIOC_MOPS_fnc_raidSide = {
	private _s = (call VIOC_MERC_fnc_sides) select {_x in [west, east]};
	if (_s isEqualTo []) exitWith {sideUnknown};
	_s select 0
};

//--- [a, b] -> true si la recta no cruza mas de 350 m de agua seguida
VIOC_MOPS_fnc_dry = {
	params ["_a", "_b"];
	private _n = ceil ((_a distance2D _b) / 100);
	private _run = 0;
	private _ok = true;
	for "_i" from 1 to _n do {
		private _p = _a vectorAdd ((_b vectorDiff _a) vectorMultiply (_i / _n));
		if (surfaceIsWater _p) then {_run = _run + 100; if (_run > 350) then {_ok = false}} else {_run = 0};
	};
	_ok
};

//--- [bando, capital] -> punto de salida o []
VIOC_MOPS_fnc_raidStart = {
	params ["_side", "_cap"];
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _cp = getPosATL _cap call VIOC_MERC_fnc_p0;
	private _pts = (CTI_Towns select {(_x getVariable ["cti_town_sideID", -1]) == _sid}) apply {getPosATL _x call VIOC_MERC_fnc_p0};
	private _hq = [(_side) call CTI_CO_FNC_GetSideHQ] param [0, objNull];
	if (_hq isEqualType objNull && {!isNull _hq} && {alive _hq}) then {_pts pushBack (getPosATL _hq call VIOC_MERC_fnc_p0)};
	_pts = (_pts select {private _d = _x distance2D _cp; _d >= (VIOC_MOPS_RAID_R select 0) && {_d <= (VIOC_MOPS_RAID_R select 1)}}) apply {[_x distance2D _cp, _x]};
	_pts sort true;
	private _res = [];
	{
		private _p = _x select 1;
		private _q = _p getPos [150, _p getDir _cp];	//--- hacia la capital, en un camino si hay
		private _r = (_q nearRoads 150) select {!isNull _x && {!(surfaceIsWater (getPosATL _x))}};
		if (_r isNotEqualTo []) then {_q = getPosATL (_r select 0)};
		_q = [_q select 0, _q select 1, 0];
		if (!(surfaceIsWater _q) && {[_q, _cp] call VIOC_MOPS_fnc_dry} && {!([_q, VIOC_MOPS_HIDE_R] call VIOC_MERC_fnc_nearPlayer)} && {!([_q, 1500] call VIOC_MERC_fnc_seen)}) exitWith {_res = _q};
	} forEach _pts;
	_res
};

//--- [bando, capital, salida] -> true si salio
VIOC_MOPS_fnc_raidSpawn = {
	params ["_side", "_cap", "_start"];
	private _z = createHashMapFromArray [["id", "raid"], ["kind", "raid"], ["side", _side], ["groups", []]];
	([_z] call VIOC_MERC_fnc_newRoster) params ["_roles", "_vehs"];
	_roles = _roles - ["boss"];	//--- sin jefe: ni recompensa ni aviso de jefe muerto
	if !([count _roles] call VIOC_MERC_fnc_room) exitWith {["ataque: sin presupuesto de IA, se espera"] call VIOC_MOPS_fnc_log; false};
	[count _roles] call VIOC_MERC_fnc_reserve;
	private _g = createGroup [_side, true];
	private _men = [];
	{
		private _u = [_z, _g, _x, _start getPos [5 + random 15, random 360]] call VIOC_MERC_fnc_mkUnit;
		if (!isNull _u) then {_men pushBack _u};
	} forEach _roles;
	if (_men isEqualTo []) exitWith {deleteGroup _g; false};
	private _vs = [];
	{
		private _v = ([_z, _x select 0, _start getPos [20 + 15 * _forEachIndex, random 360], false] call VIOC_MERC_fnc_mkVehicle) select 0;
		if (!isNull _v) then {_vs pushBack _v; _g addVehicle _v};
	} forEach _vehs;
	//--- a bordo: conductor y artillero primero; el jefe de equipo (primero de la lista) sube al final
	private _free = +_men;
	{
		private _v = _x;
		if ((_v emptyPositions "Driver") > 0 && {_free isNotEqualTo []}) then {private _u = _free deleteAt ((count _free) - 1); _u assignAsDriver _v; _u moveInDriver _v};
		if ((_v emptyPositions "Gunner") > 0 && {_free isNotEqualTo []}) then {private _u = _free deleteAt ((count _free) - 1); _u assignAsGunner _v; _u moveInGunner _v};
		while {(_v emptyPositions "Cargo") > 0 && {_free isNotEqualTo []}} do {private _u = _free deleteAt ((count _free) - 1); _u assignAsCargo _v; _u moveInCargo _v};
	} forEach _vs;
	private _cp = getPosATL _cap call VIOC_MERC_fnc_p0;
	_g setBehaviour "AWARE";
	_g setCombatMode "RED";
	_g setSpeedMode "NORMAL";
	private _w = _g addWaypoint [_cp getPos [450, _cp getDir _start], 50];
	_w setWaypointType "MOVE";
	_w = _g addWaypoint [_cp, 120];
	_w setWaypointType "SAD";
	_w = _g addWaypoint [_cp, 120];
	_w setWaypointType "GUARD";
	VIOC_MOPS_RAID_INFO = [_cap, _men, _vs, _start, _g, time];
	private _sn = [_side] call VIOC_MERC_fnc_sideName;
	private _txt = format ["Inteligencia: %1 contrato mercenarios de ION para atacar %2 (la capital).", _sn, _cap getVariable ["cti_town_name", "la capital"]];
	{ [_txt, _x] call VIOC_MERC_fnc_say } forEach ((call VIOC_MERC_fnc_allPlayers) select {(side (group _x)) in [west, east, resistance] && {(side (group _x)) != _side}});
	[format ["ataque a %1 de %2: %3 hombres, vehiculos %4, salida %5 (%6 m)", _cap getVariable ["cti_town_name", "?"], _side, count _men, _vs apply {typeOf _x}, mapGridPosition _start, round (_start distance2D _cp)]] call VIOC_MOPS_fnc_log;
	true
};

VIOC_MOPS_fnc_raidTry = {
	private _side = call VIOC_MOPS_fnc_raidSide;
	if (_side isEqualTo sideUnknown) exitWith {};
	private _cap = call VIOC_MERC_fnc_capital;
	if (isNull _cap) exitWith {};
	if ((_cap getVariable ["cti_town_sideID", -1]) == ((_side) call CTI_CO_FNC_GetSideID)) exitWith {};	//--- ya es suya
	if (!isNil "VIOC_FL_fnc_isRear" && {[_cap] call VIOC_FL_fnc_isRear}) exitWith {};	//--- retaguardia de su duenio: no se ataca
	private _st = [_side, _cap] call VIOC_MOPS_fnc_raidStart;
	if (_st isEqualTo []) exitWith {};
	if ([_side, _cap, _st] call VIOC_MOPS_fnc_raidSpawn) then {VIOC_MOPS_RAID_STATE = "en curso"};
};

VIOC_MOPS_fnc_raidLoop = {
	waitUntil {sleep 5; VIOC_MERC_READY};
	while {VIOC_MOPS_RAID_STATE == "espera" && {!(missionNamespace getVariable ["CTI_GameOver", false])}} do {
		if (time > VIOC_MOPS_RAID_T1 && {!VIOC_MOPS_RAID_FORCE}) exitWith {VIOC_MOPS_RAID_STATE = "descartado"; ["ataque inicial descartado: fuera de plazo"] call VIOC_MOPS_fnc_log};
		if (time >= VIOC_MOPS_RAID_T0 || {VIOC_MOPS_RAID_FORCE}) then {call VIOC_MOPS_fnc_raidTry};
		sleep 30;
	};
	if (VIOC_MOPS_RAID_STATE != "en curso") exitWith {};
	VIOC_MOPS_RAID_INFO params ["_cap", "_men", "_vs", "_start", "_g", "_t0"];
	waitUntil {sleep 30; ({alive _x} count _men) == 0 || {(time - _t0) > VIOC_MOPS_RAID_LIFE} || {missionNamespace getVariable ["CTI_GameOver", false]}};
	VIOC_MOPS_RAID_STATE = "terminado";
	[format ["ataque terminado: %1 de %2 vivos", {alive _x} count _men, count _men]] call VIOC_MOPS_fnc_log;
	private _left = _men + _vs;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		_left = _left select {!isNull _x};
		if (_left isEqualTo []) exitWith {};
		{
			if ([_x, 900] call VIOC_MERC_fnc_canDel) then {
				if (_x isKindOf "Man") then {
					if (isNull (objectParent _x)) then {deleteVehicle _x} else {(objectParent _x) deleteVehicleCrew _x};
				} else {
					private _v = _x;
					{ _v deleteVehicleCrew _x } forEach (crew _v);
					deleteVehicle _v;
				};
			};
		} forEach _left;
		sleep 30;
	};
	if (!isNull _g && {(units _g) isEqualTo []}) then {deleteGroup _g};
};

VIOC_MOPS_fnc_raidNow = {
	VIOC_MOPS_RAID_FORCE = true;
	if (VIOC_MOPS_RAID_STATE == "descartado") then {VIOC_MOPS_RAID_STATE = "espera"; [] spawn VIOC_MOPS_fnc_raidLoop};
	"ataque pedido: sale en menos de 30 s si se cumplen las condiciones (ver VIOC_MERC_DEBUG = true)"
};

VIOC_MOPS_fnc_info = {
	private _cap = call VIOC_MERC_fnc_capital;
	format ["merc_ops: ataque inicial %1 (parametro %2), sirven a %3, capital %4 (duenio %5), %6 hombres del ataque vivos; ultimos pueblos %7, zonas de ultimos pueblos %8",
		VIOC_MOPS_RAID_STATE, ["no", "si"] select VIOC_MOPS_RAID, call VIOC_MERC_fnc_sides, _cap getVariable ["cti_town_name", "?"], _cap getVariable ["cti_town_sideID", -1],
		{alive _x} count (VIOC_MOPS_RAID_INFO param [1, []]), ["no", "si"] select VIOC_MOPS_LAST, {(_x get "kind") == "last"} count VIOC_MERC_ZONES]
};

if (VIOC_MOPS_RAID) then {[] spawn VIOC_MOPS_fnc_raidLoop};
diag_log format ["[VIOC merc_ops] activo: ataque inicial %1, ultimos pueblos %2", VIOC_MOPS_RAID, VIOC_MOPS_LAST];

class VIOC_MERC_RAID {
	title = "VIOC: Mercenarios: ataque inicial contra la capital (una vez, entre los 10 y 45 min, pagado por el bando al que sirven si la capital no es suya; con el presupuesto de IA)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
class VIOC_MERC_LAST {
	title = "VIOC: Mercenarios: defienden los ultimos 2 pueblos del bando al que sirven";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
